-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('57f0df42-c9b8-5fc9-83f0-8b086bd2f401'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('840ab3da-db7e-55af-9807-325bfd745be1'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('7fec7e42-fdf4-538c-b669-21ac72cc942d'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('70cc1bb1-11a2-58f4-88f2-ee60f22993a5'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('364e5cb8-55fb-54b3-ba27-be02e0e07657'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('256d35d2-df43-5951-a43d-8ea0e574b9b3'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('496e0c4f-8080-5596-9c0f-31089f276d65'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('09d01da1-2074-57b2-b6d3-56bcfb101582'::uuid, '8b56d015-c2f6-575f-91a7-7dbf4b2cf755'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('52fc54a0-6fd3-5fc4-b9b0-6ad86bbf5122'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('cd67772b-29bf-5ee8-a102-71f5f80ecde5'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('a51af759-d923-569d-b427-6edcc681457b'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('55bfc0b4-094f-5dd2-adb3-fedca9ccbc0c'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('e666bcba-6910-5ad8-9ca2-3da4f1c2363e'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Comment dit-on « ne… plus » ?', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no fumo* : je ne fume plus. *Todavía no* signifie « pas encore ».', 5),
    ('725d103c-78e4-523d-bae2-b93cfc68f74b'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["Sino","Pero","Porque","Aunque"]'::jsonb, 0, '*No es francés sino español.* *Pero* oppose sans rectifier.', 6),
    ('678783b8-a22d-5f4d-a508-d8beaae0243b'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('a79f1352-1c42-544a-8d33-308ae471b71c'::uuid, '7ba9077d-c209-57a4-895c-edd4d3f290fa'::uuid, 'Devant un verbe conjugué, « sino » devient…', 'mcq', '["Sino que","Sino de","Sino a","Sino el"]'::jsonb, 0, '*No canta sino que grita.*', 8),
    ('e0f56b87-0aa2-530b-a76e-ceea5c7bf432'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('65fb9b4b-9a01-5cea-b265-e3b3b8eba3dc'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('c3a5b6f2-d002-5f70-8795-3c8c7f9b0653'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('4aee86bb-9238-55c3-873a-c49bb2798c41'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('adbbd87f-e76c-503a-b1ca-bd113548b7c3'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'Après « No conozco a nadie que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au gérondif"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini.', 5),
    ('702b4e95-6572-502b-8147-44ab238d31ff'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'Pour renvoyer à une idée entière, on emploie…', 'mcq', '["Lo que","El que","Quien","Cuyo"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 6),
    ('0063756f-2bf1-5a09-98b3-f6833c226389'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('e1512da7-0663-5bc1-9728-089cb1603cdb'::uuid, 'f63b1396-ca6f-5393-a94c-554bd58ac0ab'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('81de982e-6f7a-55e0-8c5a-337eb56494d3'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Après « Quiero que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au conditionnel"]'::jsonb, 0, 'La volonté commande le subjonctif : *Quiero que vengas.*', 1),
    ('7704093b-279e-5988-9365-e87f92ded21a'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('9e9840f1-1b1a-5fad-a734-c77d1fbcd956'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('83b9223d-f5f3-5c4f-8c49-2d2f22f8543e'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Après « Es necesario que… », on emploie…', 'mcq', '["Le subjonctif","L’indicatif","Le gérondif","Le participe"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif : *que estudies*.', 4),
    ('f80c2b44-7ac0-5669-981f-18907744e781'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('47e7b2e5-22a9-56f8-a12a-0158fd8d9ff3'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('c274fc6e-0d31-5b98-9fb5-8aa043f4b31f'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('8a30429e-aefc-5045-a103-5356f8998a1c'::uuid, 'f881049e-12ed-55c3-a3c0-3dc63188cc1c'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('e5aec682-1ac2-5c67-9495-8f7134388bc6'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('4fbdbf91-e774-5c57-8fde-e5db106ec350'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('2f8021e9-606a-52d7-b15a-732308e9f54d'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('f9b374d6-40f0-5c30-bada-6717dc728f7f'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('4c1db4fc-161d-5114-8eb7-e2d85f7c27c7'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('e6992e67-7231-5360-847e-0d72becd0141'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('c3030dc9-cb5d-523f-acd5-b5096c470781'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('d29f38fc-3426-5f45-b123-6ea5fedb1cf3'::uuid, '605b7e33-15ba-5a12-a668-c96ee8d074b7'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('d827c434-fc39-587e-8746-9cac7a145790'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('6e6cc220-44fb-58fe-956a-7a93f7e9a824'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('a0db556b-bea6-5753-9ed5-dcd7bf777f17'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('a467b57b-e13a-5ed6-b727-2b5ebaef2a28'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('ad921c4e-d240-5519-9e2d-2cd54534db1a'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('2e77781e-b79d-5dc2-a29e-a1049d734aec'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('d8f01ca0-255b-51eb-bed3-3dd9859cdbc9'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('1b1fb3a4-a28c-52e1-bf26-b00341f8d471'::uuid, '3d746d9d-d9e0-5bf3-8836-075c0b01de20'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('a3ee8b5d-b0ba-5ea6-b781-e8a44bfb33fc'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('ded4f978-9ae9-59dc-bbc1-d2d6066f46e9'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('ecd9b479-8e76-5e49-a2f7-4dd60de85af5'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('1b6b75f9-b4f6-5ec8-8fdb-2a4ba735246e'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('5a227435-86ba-5505-964e-badf7f923979'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('e13b8685-7adc-51e6-9d60-a06882928ad9'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('45c26845-b9cb-5d49-88d3-df34679a68f2'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, 'Comment traduire « qu’est-ce que c’est ? » ?', 'mcq', '["¿Qué es esto?","¿Qué es este?","¿Qué es ésta?","¿Qué es aquel?"]'::jsonb, 0, 'La chose n’étant pas identifiée, on emploie le neutre.', 7),
    ('374ab209-c14e-584a-8c34-2c8a085e758d'::uuid, '2cb8e9a3-a3e5-5b55-b203-ba666d727edb'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('bfe3b068-4a79-59fa-9dc6-76865929fdf9'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('501d11fa-c96b-5216-b3da-c129d2101b11'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('f9dce2ea-41fb-5ca2-b7d8-74a4a0ab831d'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('0b366489-a61b-5eca-bef3-ea259c63786e'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('6e7d8b15-0367-524e-88be-13878c624e70'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('00b41a14-1e72-5e22-924b-0d14932610ac'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('240ba13a-9820-5a75-84af-de8ad661dc3b'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('cfe82e73-ac3f-5c6f-b6cd-f9561feecdaf'::uuid, 'dc2d0dae-c0ed-5292-b311-8d59f4e30470'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('fbb18f38-06d3-590a-b1cb-edea7177720d'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('aa520b59-1f91-5b4c-890d-338ede30afb1'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('075dfdfb-ca20-5f0c-9a66-8f93b69811ab'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('3b1f3089-d03d-575c-a0c8-4231caaf0c83'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('e6535f40-b954-579d-9988-9ce6751b6ffc'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, 'Comment traduire « pour moi » ?', 'mcq', '["Para mí","Para yo","Por yo","Para me"]'::jsonb, 0, 'Après préposition, *yo* devient *mí* et *tú* devient *ti*.', 5),
    ('42d9519e-fb07-5318-b6a9-b86c287ec83d'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('d306df82-f192-5ce7-92fa-f7a70101c467'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, 'Après « entre » et « según », quel pronom emploie-t-on ?', 'mcq', '["Tú et yo","Ti et mí","Te et me","Usted seulement"]'::jsonb, 0, '*Entre tú y yo*, *según tú* : ces prépositions font exception.', 7),
    ('60683f6d-a517-598a-9274-2a9b19e1d908'::uuid, '85c37e52-b761-5186-83f5-2fd888c8cea4'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('b5f6525c-3c29-50d0-b532-f1a0f1879a63'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('6e236966-7ea9-54c6-a7e4-75c7e992dace'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Que devient « le » devant « lo » ?', 'mcq', '["Se","Lo","La","Les"]'::jsonb, 0, '*Se lo doy* : « le lo doy » n’existe pas.', 2),
    ('84325dfd-ff1b-5bb3-80bf-99828a403486'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('d791a2d2-1ab8-5cb8-a94c-17303602c748'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('8acb510a-927f-527f-b4ac-ce6e2c8ff4b8'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('c93c888f-82cb-5593-bd8c-03d58378a1e5'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('b4618b68-c47b-58af-9fa7-7713f335cb30'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('97f9d340-c78a-5c76-8cc8-4406908c0124'::uuid, '74c88572-7614-51a2-98d2-4ce6cd793fd6'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('6536b492-641c-54f3-b7b0-7bbe9daafdef'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('3e73f558-a43c-5dcf-a53e-c3f1e95bde8f'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Comment traduire « je me lave les mains » ?', 'mcq', '["Me lavo las manos","Me lavo mis manos","Lavo mis manos","Me lavo mías manos"]'::jsonb, 0, 'Corps et vêtements prennent l’article défini, pas le possessif.', 2),
    ('a65f1dc8-f634-54ef-bd82-aaa4bc6bf07c'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('869febf5-1f61-536e-b1de-8e5db306a4aa'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('4cd9b6ac-e478-5e76-a5c4-71b60277d2d7'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('db5138ab-d3d4-55b4-9287-c1c9c61b200c'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('3b65cc91-bdac-5278-8ab0-88622600d0f3'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Comment traduire « il a mal à la tête » ?', 'mcq', '["Le duele la cabeza","Le duele su cabeza","Duele su cabeza","Tiene mal su cabeza"]'::jsonb, 0, 'Le pronom *le* porte déjà l’information de possession.', 7),
    ('0c8abbb6-a204-56d9-bd56-011bc38d4eda'::uuid, 'b7acf3a4-334a-579c-a4d0-a712b44b6d65'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('4842345e-a7e0-5b24-bd7b-d9c5f2b59da0'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('12072127-61b4-533c-ae18-9596a9bd9ae2'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('d00e297d-d2b5-5541-bf20-82f351506509'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Quel relatif s’emploie uniquement pour des personnes ?', 'mcq', '["Quien","Que","Cuyo","Donde"]'::jsonb, 0, '*La persona con quien hablo.*', 3),
    ('3700c08b-401b-5308-ada3-1b1e80c76bec'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('85bae20d-a894-5076-9c19-f9ffca03b578'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('a2d72981-ca3e-5cde-81d4-55da93cf84d3'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('e1512f08-c3ff-5b7e-b6e1-3473d4805894'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, 'Comment demander « à qui est-ce ? »', 'mcq', '["¿De quién es?","¿Cuyo es?","¿Que es de?","¿Quien es de?"]'::jsonb, 0, '*Cuyo* ne s’emploie jamais dans une question.', 7),
    ('77c619d1-219c-5d5a-9b7b-68ac7fb99199'::uuid, 'bb145049-357e-50b7-b0d8-009666ac1b2f'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('35d5e107-bcfc-500d-9fba-1666a5c95ee2'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('c6c58df0-5586-50de-8081-a76c615d9ece'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('3f604d72-65b8-5ad3-b30c-f41e1eeae230'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('30bc4c19-1d23-5d2c-a42a-d7cfc57b4aa6'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('af00de70-8341-5034-8f47-f1924351820b'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('c2ffcde4-182f-5a80-9690-c0e3dce678c2'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('80c974ff-c000-569e-802a-293a95f619c5'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('4cfb70b4-193c-5322-bc9c-dc40fa7afc54'::uuid, '870f3cb8-ee86-57ea-b91c-a2cd719d22cc'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('87067dac-a8b3-5f13-b3c3-80ad9aec371e'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Comment traduire « aussi grand que toi » ?', 'mcq', '["Tan alto como tú","Tanto alto como tú","Más alto como tú","Tan alto que tú"]'::jsonb, 0, '*Tan* devant un adjectif, *como* comme second terme.', 1),
    ('0ea6aeda-1fa7-56a2-ad97-97b10b75e814'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Comment traduire « autant de livres que toi » ?', 'mcq', '["Tantos libros como tú","Tan libros como tú","Tanto libros como tú","Más libros como tú"]'::jsonb, 0, '*Tanto* devant un nom, et il s’accorde : *tantos libros*.', 2),
    ('ebb15c8e-21c0-529f-8e93-9c5289b089de'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('227b8380-6082-5392-a130-e1c8709578c3'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('da5e44d4-6529-54c4-9e3c-64344aecfa56'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('fa7e7db2-c065-5bc9-9d9e-bf6dae81a2f5'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Quel est le comparatif de « malo » ?', 'mcq', '["Peor","Más malo","Menor","Mal"]'::jsonb, 0, 'Comme *bueno → mejor*, *grande → mayor*, *pequeño → menor*.', 6),
    ('328b019d-734b-51f0-9e95-52621cd96d18'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('7949c9f9-854d-5ea8-a532-c0643bd38114'::uuid, '39ee93d7-7478-5138-84da-c592c671118f'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('7bfcc32e-8387-5fbd-b276-ea81f9b8fd3f'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Comment traduire « le plus grand du monde » ?', 'mcq', '["El más grande del mundo","El más grande en el mundo","El mucho grande del mundo","El más grande que el mundo"]'::jsonb, 0, 'Le complément du superlatif relatif se construit avec *de*.', 1),
    ('81b4b735-0a12-5c03-8e20-0143f3a574b6'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('1a2e7482-1e97-5611-865e-abc6a8077825'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Quel est le superlatif absolu de « rico » ?', 'mcq', '["Riquísimo","Ricísimo","Rikísimo","Ricoísimo"]'::jsonb, 0, 'Le c devient qu pour conserver le son [k].', 3),
    ('b6205850-b767-5ce5-8983-af31c0b59732'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('d08bf6d4-e9e4-599e-822d-2b0c39cbe8f1'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('a89b1bfa-cae0-5b88-a150-ea563b859c84'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('76d90b76-08f3-5049-84db-80b892fe676b'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('a8df3070-f393-5ea0-a06a-62adcbb7aa8d'::uuid, '15b859d3-d1f5-5c4c-a241-7d42d6bdc690'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('1e9c8bea-bad7-58fd-8a3e-6e13ce264697'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, 'Quelle est la forme apocopée de « bueno » devant un nom masculin ?', 'mcq', '["Buen","Bue","Buenó","Bon"]'::jsonb, 0, '*Un buen amigo*, mais *un amigo bueno* garde la forme pleine.', 1),
    ('1cc21035-568f-5e4d-9a61-5080828ff8eb'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('cf394c62-35ff-55d4-b02e-78da1cfb83e0'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, 'Comment dit-on « cent euros » ?', 'mcq', '["Cien euros","Ciento euros","Cientos euros","Cien de euros"]'::jsonb, 0, '*Ciento* s’apocope devant un nom, et devant *mil* et *millones*.', 3),
    ('ade7f540-8e33-50bc-b455-e51db4803be1'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('ffd33adf-f4ac-5154-8d7f-dcc5aa0cb416'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('7211e748-b7e8-54c1-b7ec-b0618550165b'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('b651348e-06ed-56b5-a946-fd3c72a091eb'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('5b656de6-95e1-5101-b3da-34dbad490a13'::uuid, 'e2d5dbeb-0cb1-5737-abfe-3289fe162310'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('670f53b5-4526-55ed-aadd-aa9005b9709c'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('60cedbf4-33fa-5c07-89be-36fc2bd5281f'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('4fde066c-f816-504b-b2e8-320ce5f84953'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('f521694b-0fa4-5d75-8341-323c7fccec29'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('343ef0e1-dabf-5f06-b27a-cdf958a9cc75'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('09e9bd11-6031-5abb-9b53-0c07443d89f7'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('43d23ac5-d88a-5936-b1a9-d5c27e8de31d'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('45f547bf-bcda-504e-8b4d-e068203dbd8e'::uuid, '9a9cb70a-2b84-5ebd-b362-30ebd712b39a'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('274bba2b-be2a-5abd-ab11-a74b0bd63026'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('8b2fd4a6-760b-5bea-91bf-5af91a55cd68'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('815739df-3c5d-5930-8e76-ef74bcf01b6e'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('7c315e3c-f8b5-585b-ab34-8c71036e9ba1'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('6dda4a77-bc2b-5e63-a74a-924f508fa9fd'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('cf47d6db-2903-512b-8e54-c70d7519940f'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('45673770-bfb2-5682-8aba-8194a4b423a1'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('63a11aca-26a1-52bc-a373-7ab4e121fecf'::uuid, '8726a88a-17eb-5882-9b16-a430e3c67c87'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('8dbb16a4-be9b-5fd0-94c4-a2d0f9382637'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('404d0325-f082-5c99-a219-a8b24a614174'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('ccde78d7-c01e-52a6-b1b5-f1df5cd2f498'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('b8943804-1f0f-5a70-91be-427178f28034'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('a2d06b18-83d4-51b3-9502-89fc20643e3e'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('1e7ed200-9bb6-5d99-83a2-e9ed6d386aec'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('a6d2adb1-b653-52ee-9dcb-a1b9f2650b16'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('60b53431-fcc6-5c39-8554-c23f662e9e97'::uuid, 'ef63f945-7e74-5779-bd29-c4ca4fe1086c'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('e8ee966f-262d-510b-a59f-e882b3106c30'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('cf0402e8-1873-59c7-9288-d3bd5ae8a36e'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('3da65d30-7053-501c-8469-4d7ff188a2eb'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('c43cd1b9-44ac-5326-9888-662e07a501db'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('eb16cc42-6c91-51cf-8bbf-647828e6b5a9'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('81c8b861-716f-53f3-bca2-122a1912f64a'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('8950c85e-9920-50f9-891e-b0053fe5bb1c'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('92432791-98ff-5d01-9b6d-0d7d21d862bd'::uuid, '77692ebb-4770-5855-a00d-02041d4c95ef'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('557cfdce-eab7-5143-b420-a625372e4404'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('415862ed-d708-522b-a7f3-548c5025241a'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('5a92d500-2af2-5bed-aaca-04a1a96fe735'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('35a01db0-5cce-54a6-a5ac-154955cd6083'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('193ff9e5-8245-52a8-87d5-44ca3cda113e'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('68aa63fa-6998-532f-a236-359e7a7c2dde'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('7c04c402-2801-547f-9f22-ebab75c461b4'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('f216452e-2857-57ac-8ebd-33068284c845'::uuid, '40b71a89-6c41-5ea6-b5fd-fbb0d3a37dcf'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('a01bde6c-0c50-532e-8b26-5adb09c19b60'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('8ed0c558-6736-577c-94c1-deec8b7d74a2'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('1648b890-e465-535c-9094-0a79719d0474'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('358a6a78-68db-5335-a10f-1efbf8bb52a4'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('9471cb8a-9420-5edd-b59f-e7e37daacab9'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('2bb00301-56cb-520a-8691-8ae77286fb3d'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('200d811e-15a1-59ec-9362-00c966a24239'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('5ec2ec25-665a-5fc2-911d-44e5d017d6d1'::uuid, '9dbfa6e5-5154-5b5f-9858-c96da5a49178'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('6ba1d495-4732-5b3f-9a9e-e5eb26148e3e'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('bd469ed7-50a1-5fd9-8c47-4046805cf60e'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('0072df1f-7cc7-527c-b1c0-579c25f13c77'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('52726abe-36e8-5a6f-b7b2-a28b016104ae'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('4386d677-51a7-5b04-838e-825b2f52eaf1'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('44e53b59-abf7-5c44-b378-8723bddc6bdd'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('22303b4b-658e-5664-91bd-ff77254c2f3a'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('da57772f-b8ff-5e58-b7d2-5232cd50d3e4'::uuid, '58569832-6ae2-56af-a869-8fb5bed507ff'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('1c52a0ef-4aff-529a-a304-131fa8cf56f7'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('c0ed5534-739b-58fb-ba11-091080544593'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('359ec213-0590-50af-b575-255c4d3a9e64'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('9a5cf2b0-74a4-5dbb-b76c-79c193f21f3b'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('98ec09ce-7db8-596a-9798-6e47f0ed12dd'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('4d41c2e1-ebb4-569b-8119-58a622ca95a6'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('ad2d0385-f876-5061-9897-9d28e39e5ac4'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('a6a965a3-0faf-5036-b4c4-caca618276dd'::uuid, 'efb5e6ba-fa08-5cc3-8e21-ab06021dfdd4'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('44f0b0a1-616c-5bc0-962e-902c9ba3729f'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('2d6ec205-0758-525d-8d37-7fbc4afbe087'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('4e3e65b0-81fa-5cea-b459-9b5d572ff36a'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('8c078ecc-de84-5489-a28b-7aa94b1d7508'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('2bea3019-f027-5dea-a237-40b22b36c42f'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('06d353ad-48d8-508e-a2ac-a35e317f2bda'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('8be512e6-24a2-5423-80fa-f1945468361e'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('7efa796d-6bfe-527d-b112-ed5c55a05712'::uuid, 'b7e125c6-428d-50c0-bda4-79916f851350'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('557e02aa-c5bf-5b3c-962e-2d5772864c66'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('96b1c9a9-83cf-51fa-97a6-7b67a7707b3f'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('f815ebc5-0009-54e3-9944-4f42badc7ba4'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('4a92626a-32ff-52e2-a047-e34d1f6d0749'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('21fe8d7b-3494-520e-881f-10ec7cb99f05'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('e5b3f029-fd75-5ec8-93a0-db4db2fd3190'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('c17b914a-ee3f-5b48-82bb-4e41cf51524f'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('24def678-9c1b-5332-993b-fb379b2c39fa'::uuid, 'fb4180dd-75bf-5606-8137-c58d7a3f91f5'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('60453fce-8e01-55e4-b946-44ca80e89938'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('1c78e6e1-7c95-5c83-a910-4ebc58307455'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('403f2477-5003-5e47-8439-fc26496c8491'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('b492f113-23b8-5597-a604-aa57c7a4706d'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('28ec166d-19a9-5949-8082-87043f315b3b'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('468f9085-228c-566a-9770-0b11a240f76e'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('86a79ec5-137c-56fb-a9fd-6a88e765f15c'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('8a44eb38-859b-5c1a-a1fd-c3c04348345b'::uuid, '43447053-ecb6-57c5-9fdc-0f4e7061148e'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('59945987-b429-5c5e-b1da-d98a16289d0e'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('cf35f515-ace5-5f80-8d6e-f227bb5606b4'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('bb2027a8-22b9-5331-b249-46ceb10bda2c'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('7bf87f9f-6ef4-5561-9ffb-c0c0e0db6153'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('a000d0d8-2222-5884-8327-97b8b846dc2f'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('40d69f17-4943-5468-9e67-2bbfd08a166a'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('01039aa0-39cb-57d5-9366-58e08a3e3e51'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('257b0c47-44a7-59f2-ac9a-16e40a5f2ce4'::uuid, '3574811d-63f7-5ba4-a56f-f917c41afc92'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('edaec208-6af1-5d1d-a940-88040fa62e22'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('ce9d9139-7979-55d1-a99f-77124a5571fe'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('3fc6b556-8696-5e0a-8875-6247b17c44aa'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('e7240ba2-9bed-5fce-a7e8-8c3820c015d6'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('34869f48-0bdb-59b7-9c1a-102c210f48be'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('158b791e-2be6-5c51-9eba-4cd17a11049c'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('5500016b-fba9-5eb2-822f-d001cfe3daf0'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('282e1521-8410-53cb-b705-1a8b8c91e33e'::uuid, '9a247ee0-482f-5351-aaf0-331c70c95dff'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('46bc87ee-0604-5d1a-b51c-9f228c3bf5f8'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('b42fbaa0-b5ff-533e-974b-871bac3ed934'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('abb76a12-3edb-5bf9-a652-9506d89919b3'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('a472207f-29b4-50e1-970d-817b38e9f8b9'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('fcf536cf-9367-5e07-b2f1-942dd31e6d60'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('304dddca-9ff0-5326-ad46-cbebaf80b4c3'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
    ('86339398-548a-5476-a3c8-de1c014b2536'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Quelle conjonction est toujours suivie du subjonctif ?', 'mcq', '["Para que","Porque","Aunque toujours","Ya que"]'::jsonb, 0, 'Comme *antes de que*, *sin que*, *a menos que*.', 7),
    ('9e708a6a-47eb-5346-bb64-57c895dfd77b'::uuid, '918eb76b-8c6a-58ed-8a63-77946cf326aa'::uuid, 'Quel est le subjonctif présent de « ir » ?', 'mcq', '["Vaya","Vaiga","Iría","Fuera"]'::jsonb, 0, 'L’un des six irréguliers dont la 1re personne ne finit pas par -o.', 8),
    ('deea70dc-cd28-55c1-8a6c-3c792ad3d153'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'Combien de verbes sont irréguliers à l’imparfait ?', 'mcq', '["Trois : ser, ir, ver","Aucun","Six","Dix"]'::jsonb, 0, '*Era*, *iba*, *veía* — la seule liste courte de la conjugaison espagnole.', 1),
    ('b03734b0-56a2-5ddf-abf4-f0cf4f01f421'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'Quelle est la terminaison de l’imparfait des verbes en -ar ?', 'mcq', '["-aba","-ía","-ió","-aría"]'::jsonb, 0, 'Les -er et -ir font *-ía*.', 2),
    ('3c59b6fb-24b0-5307-b1ff-54e3519140b3'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('4fe4dd95-bde7-5666-b27f-20d211e9153c'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('407d6085-f50c-50e0-b0d0-235279e29291'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('5b40dab2-e46a-54dc-9943-c1cb6b2cc578'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('8d523dea-6d0e-5221-b879-b44824af7b40'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('79cb6e41-4da9-595e-9948-9601ef0ff39a'::uuid, 'f565f429-f883-574a-9380-6f698e957c3c'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('7db82c92-5b18-53fc-b54e-7d2f05bb0a85'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('08362312-64cb-5d2a-a6b4-4870cd5f7453'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('87dc1e80-66f5-5609-b835-3e482b64fc64'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('13fa1b59-25af-5a00-9d9a-2adb524c3ad1'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
    ('f01760bb-50dc-5c7c-ab59-88f7d361c142'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'Quelle est la différence entre « Hoy he ido al cine » et « Ayer fui al cine » ?', 'mcq', '["Le premier appartient à une période non achevée","Aucune","Le premier est plus soutenu","Le second est un plus-que-parfait"]'::jsonb, 0, 'Le passé simple coupe du présent, le passé composé raccroche.', 5),
    ('431a0ba6-e7a3-5fd1-b2d3-8f4bf494fedb'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('8e2669c5-dfca-536b-a592-e0ebeac1cba8'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('e18a0dc3-2a5c-5260-ab20-9fb2c6cb37cf'::uuid, 'c3ef88a0-6e1c-5672-bf08-4083f0076dd9'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('670f24e0-35f7-5afb-9585-3f42d31d2569'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('76954271-3cc0-525a-b299-9ef1e83d7f4d'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('cbaf4879-98fa-5257-9123-fd71cafce825'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('c051df26-b89b-52e3-ae1c-f6e48ccc02ab'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('69e9a547-9c89-5d99-a810-81695849baae'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('1fe35d0c-4bc0-5436-a6b3-a2ce50140d52'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('7edbfbba-2314-51d0-8baf-555df68feb97'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('2d29e07c-e49a-5443-bc17-21baef9ce2bf'::uuid, '25001158-3c5d-53f2-a081-66422a5d1b47'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('8cca198d-fa88-5270-becf-6ad4777aee8b'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('110ff9f8-b920-5350-adb4-a3fda8f3fce8'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('f6962a3b-75f2-5cec-aac3-9a9ccc7dda17'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('8545e68e-c041-53ab-a8e5-694219428dd4'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('cdd41a60-c07b-5160-b76e-d641152660d7'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('f91f4148-f89c-5749-9b3a-a99d9720ff51'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('4a2bcb11-aab9-5325-931b-f2a63177e1c8'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('915f4399-dc59-58a7-aeb0-1dbc16af4b28'::uuid, '0086a282-ab64-56f4-b78b-4ed0940e2ecd'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 287 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 287 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
